key = [l.split("=",1)[1].strip().strip('"\'') for l in open(os.path.expanduser("~/.secrets/api_keys.env")) if l.startswith("OPENROUTER_API_KEY=")][0]
F = {
"A":("check_that_cannot_fail","A check, test or verification that passes (or would pass) even when the claim is false: an existence check graded as verification, a swallowed error, a substitute object checked instead of the real one.","A wrong claim that one available check would have disproved (claim_disproved_by_available_check); a check made from the wrong environment (wrong_vantage_point); several agents sharing one blind spot (correlated_blind_spot)."),
"B":("untested_reasoning","A method, frame or causal story adopted without testing it against an ordinary case that breaks it; a signal treated as evidence for something it does not measure.","Use only when no more specific option fits. Not for broken checks, wrong targets, leftover state, or claims one available check would have disproved."),
"C":("parts_pass_whole_fails","Each part passed but nobody ran the whole thing end to end as its user would; completion declared over a subset; a hidden dependency on the local environment.","A single check that could not fail (check_that_cannot_fail)."),
"D":("rule_that_does_not_act","A rule, instruction or record exists but nothing makes it fire or reads it: a prohibition only in prose, a record nobody reads back, an instruction never verified as read.","A control that fires but costs too much (control_out_of_proportion); an official route that is itself broken (sanctioned_route_impassable)."),
"E":("state_left_behind","Something changed in one place while the same state stays true somewhere else: copies, mirrors or other repositories not updated; something retired but still present; shared state changed without telling its owner.","Correct steps run in the wrong order (ordering_breaks_guarantee); an empty result read as success (zero_read_as_success)."),
"F":("control_out_of_proportion","A check or gate costs more than what it protects, blocks unrelated work, or makes the correct action expensive.","A rule that never fires (rule_that_does_not_act)."),
"G":("deliverable_fails_reader","Nothing technical was wrong, but the report or message failed its reader: completion claimed without scope, internal jargon, unclear whether the reader must act.","Technical failures of any kind."),
"J":("conflicting_authorities","Two rules or authorities are both in force and cannot both be satisfied, so the agent cannot comply either way.","A single broken official route (sanctioned_route_impassable)."),
"K":("ordering_breaks_guarantee","Individually correct steps run in an order, or non-atomically, that voids the guarantee: state written before a check, two writes that can half-complete.","An official governed route that is itself broken and cannot be used (sanctioned_route_impassable)."),
"L":("wrong_target_selected","Every component works but operates on the wrong object: a flag, filter, scope or matcher selects something other than what its name says.","A correct observation made from the wrong environment or copy (wrong_vantage_point)."),
"M":("zero_read_as_success","An empty result, a zero, missing output or exit code 0 is read as success or as 'nothing there', when it actually hid a failure or lost the content.","Stale copies elsewhere (state_left_behind)."),
"N":("sanctioned_route_impassable","The official governed path (a required command, gate or workflow) is itself broken, so the agent's only moves are to violate policy or stop.","Steps run in the wrong order that still let work continue (ordering_breaks_guarantee)."),
"O":("work_above_stopped_producer","Correct work built on top of something upstream that has stopped, so it cannot move any real outcome.","Work that is itself broken."),
"Q":("correlated_blind_spot","Several agents or reviewers share the same supplied blind spot or premise, so their agreement makes a wrong answer look more convincing.","A single check that could not fail (check_that_cannot_fail)."),
"R":("partial_list_treated_as_complete","A list or set that is only a minimum, or only partly gathered, is read or written as the complete set.","Selecting the wrong single object (wrong_target_selected)."),
"S":("scope_or_authority_drift","An agent's scope or authority drifted: a recommendation treated as an order, someone else's claim treated as an assignment, the session objective replaced.","Technical failures in tools."),
"T":("built_before_measured","Something was built or researched before checking the baseline or what already existed, including the owner's own earlier work.","A wrong claim one check would have disproved (claim_disproved_by_available_check)."),
"U":("claim_disproved_by_available_check","A confident claim was stated or published when a single readily available check (reading the source, running the command, searching) would have refuted it.","A check that ran but could not fail (check_that_cannot_fail); a check made from the wrong place (wrong_vantage_point)."),
"V":("wrong_vantage_point","A real observation made from somewhere the claim does not describe (a different identity, host, checkout, profile or stale copy) and then reported as generally true.","Operating on the wrong object (wrong_target_selected)."),
"W":("unbounded_default","A request silently took a default (retry, timeout, model tier, waiting forever) whose cost is far larger than intended or unbounded.","Plain tool facts with no cost consequence (not_a_failure)."),
"X":("one_bad_record_hides_batch","One bad record or one failure aborts or hides a whole batch of otherwise independent results.","Zero read as success (zero_read_as_success)."),
"Y":("one_object_two_identities","The same real object is represented by two ids or fields, so it is counted twice or treated as two things.","Wrong object selected (wrong_target_selected)."),
}
crit = {name: {"what": what, "not_for": nf} for (name, what, nf) in F.values()}
crit["other"] = {"what": "A real reasoning or control failure that none of the other options describes.", "not_for": "Plain facts about how a tool or product behaves (not_a_failure)."}
crit["not_a_failure"] = {"what": "A plain fact, behaviour or gotcha of a tool or product; nobody's reasoning or control went wrong.", "not_for": "Cases where an agent or system made a mistake because of that behaviour."}
name2letter = {v[0]: k for k, v in F.items()}
Q = {"kind": {"type":"choice","instructions":"Which kind of failure does this learning record?","criteria":crit}}
